public static int maxRegions(int N) {
    if (N < 0) {
        throw new IllegalArgumentException("Number of triangles cannot be negative");
    }
    if (N == 0) {
        return 1; // No triangles, only the plane itself is the region
    }
    // The formula to calculate the maximum number of regions
    // formed by N triangles is derived from the fact that each new triangle
    // can intersect all previous triangles to form the maximum number of new regions.
    // The formula is R(N) = 2 * N^2 + 2 * N + 1
    return 2 * N * N + 2 * N + 1;
}

