public static String convertDatesToWeekdays(String date) {
    String[] monthNames = {"January", "February", "March", "April", "May", "June", 
                           "July", "August", "September", "October", "November", "December"};
    String[] dayNames = {"Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"};

    try {
        String[] parts = date.split(" ");
        if (parts.length != 3) {
            throw new IllegalArgumentException("Date format must be 'MM dd yyyy'");
        }

        int month = Integer.parseInt(parts[0]) - 1; // month index is 0-based
        int day = Integer.parseInt(parts[1]);
        int year = Integer.parseInt(parts[2]);

        if (month < 0 || month > 11) {
            throw new IllegalArgumentException("Month must be between 01 and 12");
        }

        // Leap year checking
        boolean isLeapYear = (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);
        int[] daysInMonth = {31, (isLeapYear ? 29 : 28), 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};

        if (day < 1 || day > daysInMonth[month]) {
            throw new IllegalArgumentException("Invalid day for the given month and year");
        }

        // Calculate the day of the week
        int[] t = {0, 3, 2, 5, 0, 3, 5, 1, 4, 6, 2, 4};
        year -= month < 2 ? 1 : 0;
        int weekdayIndex = (year + year/4 - year/100 + year/400 + t[month] + day) % 7;

        return monthNames[month] + " " + day + ", " + year + " is a " + dayNames[weekdayIndex];

    } catch (NumberFormatException e) {
        return "Invalid date format. Please use 'MM dd yyyy'";
    } catch (IllegalArgumentException e) {
        return e.getMessage();
    }
}

