    StringBuilder result = new StringBuilder();
    int n = s.length();

    while (result.length() < n) {
        for (char c = 'a'; c <= 'z'; c++) {
            if (count[c - 'a'] > 0) {
                result.append(c);
                count[c - 'a']--;
            }
        }
        for (char c = 'z'; c >= 'a'; c--) {
            if (count[c - 'a'] > 0) {
                result.append(c);
                count[c - 'a']--;
            }
        }
    }

    return result.toString();
}

